(function () {
  var reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var each = function (sel) { return [].slice.call(document.querySelectorAll(sel)); };

  // Reveal on scroll.
  var rv = each('.sec .head, .aeo > *, .step, .fr, .tile, .case, .ind, .def, .stats, .roi, .faq details, .appw, .code, .dark-grid > div, .twocol > *, .cta');
  rv.forEach(function (el, i) {
    el.setAttribute('data-rv', '');
    el.style.setProperty('--d', (i % 4) * 80 + 'ms');
  });
  var seen = new IntersectionObserver(function (entries) {
    entries.forEach(function (e) {
      if (e.isIntersecting) { e.target.classList.add('in'); seen.unobserve(e.target); }
    });
  }, { threshold: 0.12, rootMargin: '0px 0px -40px 0px' });
  rv.forEach(function (el) { reduce ? el.classList.add('in') : seen.observe(el); });

  // The results count up to their figures.
  each('.stat b').forEach(function (b) {
    var text = b.textContent.trim(), m = text.match(/^(\d+)(.*)$/);
    if (!m || reduce) return;
    var to = +m[1], suffix = m[2];
    b.setAttribute('aria-label', text);
    b.textContent = '0' + suffix;
    var obs = new IntersectionObserver(function (entries) {
      if (!entries[0].isIntersecting) return;
      obs.disconnect();
      var start = performance.now(), dur = 1400;
      (function step(now) {
        var k = Math.min(1, (now - start) / dur), e = 1 - Math.pow(1 - k, 3);
        b.textContent = Math.round(to * e) + suffix;
        if (k < 1) requestAnimationFrame(step);
      })(start);
    }, { threshold: 0.5 });
    obs.observe(b);
  });

  // The nine steps light up in turn, as a run would, while on screen.
  var steps = each('.steps .step'), k = 0, timer = null;
  var tick = function () {
    steps.forEach(function (s, i) {
      s.classList.toggle('is-run', i === k);
      s.classList.toggle('is-done', i < k);
    });
    k = (k + 1) % (steps.length + 2);
  };
  if (steps.length && !reduce) {
    var runObs = new IntersectionObserver(function (entries) {
      if (entries[0].isIntersecting) { if (!timer) { tick(); timer = setInterval(tick, 1300); } }
      else if (timer) { clearInterval(timer); timer = null; }
    }, { threshold: 0.25 });
    runObs.observe(steps[0].parentNode);
  }

  // The fraud checks tick off one by one, once.
  var checks = each('.fraud .fr');
  if (checks.length) {
    if (reduce) checks.forEach(function (c) { c.classList.add('is-ok'); });
    else {
      var frObs = new IntersectionObserver(function (entries) {
        if (!entries[0].isIntersecting) return;
        frObs.disconnect();
        checks.forEach(function (c, i) { setTimeout(function () { c.classList.add('is-ok'); }, 500 + i * 320); });
      }, { threshold: 0.3 });
      frObs.observe(checks[0].parentNode);
