  var links = each('.apx-chap a[href^="#"]').filter(function (a) { return !a.classList.contains('apx-chap-cta'); });
  var map = {};
  links.forEach(function (a) { var t = document.getElementById(a.getAttribute('href').slice(1)); if (t) map[t.id] = a; });
  var bar = document.querySelector('.apx-chap-in');
  var chapObs = new IntersectionObserver(function (entries) {
    entries.forEach(function (e) {
      if (!e.isIntersecting) return;
      links.forEach(function (a) { a.classList.remove('is-on'); });
      var a = map[e.target.id];
      if (a) {
        a.classList.add('is-on');
        if (bar && bar.scrollWidth > bar.clientWidth) bar.scrollTo({ left: a.offsetLeft - bar.clientWidth / 2 + a.offsetWidth / 2, behavior: reduce ? 'auto' : 'smooth' });
      }
    });
  }, { rootMargin: '-45% 0px -50% 0px' });
  Object.keys(map).forEach(function (id) { chapObs.observe(document.getElementById(id)); });
})();
(function () {
  var reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var all = function (sel, root) { return [].slice.call((root || document).querySelectorAll(sel)); };
