    var o = new IntersectionObserver(function (entries) {
      if (entries[0].isIntersecting) onIn(); else if (onOut) onOut();
    }, { threshold: threshold || 0.3 });
    o.observe(el);
  };

  // Nine steps: the rail and the invoice screen move through the steps in
  // turn while on screen; a step can be picked, and the run paused.
  var run = document.querySelector('[data-ax-run]');
  if (run) {
    var DUR = 4200;
    var sts = all('.ax-st', run), scs = all('.ax-sc', run), segs = all('.ax-segs i', run);
    var num = run.querySelector('[data-ax-k]'), pp = run.querySelector('[data-ax-pp]');
    var cur = 0, timer = null, seen = false, paused = reduce;
    run.style.setProperty('--ax-dur', DUR / 1000 + 's');
    var show = function (i) {
      cur = i;
      sts.forEach(function (s, j) {
