      if (num) num.textContent = (i < 9 ? '0' : '') + (i + 1);
    };
    var stop = function () {
      if (timer) { clearInterval(timer); timer = null; }
      run.classList.remove('playing');
    };
    var play = function () {
      stop();
      if (paused || !seen) return;
      // Restart the current step's bar.
      void run.offsetWidth;
      run.classList.add('playing');
      timer = setInterval(function () { show((cur + 1) % sts.length); }, DUR);
    };
