      cks.forEach(function (c) { c.classList.remove('run', 'ok', 'bad'); c.classList.add('q'); });
      all('.hit, .bad', fr.querySelector('.ax-fdoc')).forEach(function (r) { r.classList.remove('hit', 'bad'); });
      if (count) count.textContent = '0';
    };
    var finish = function () {
      clear();
      fr.classList.remove('scanning');
      cks.forEach(function (c) {
        var bad = c.hasAttribute('data-fail');
        c.classList.remove('q', 'run');
        c.classList.add(bad ? 'bad' : 'ok');
        regions(c).forEach(function (r) { r.classList.remove('hit'); if (bad) r.classList.add('bad'); });
      });
      if (count) count.textContent = String(cks.length);
      fr.classList.add('done');
    };
    var cycle = function () {
      clear();
      reset();
      fr.classList.add('scanning');
