      cks.forEach(function (c, i) {
        later(function () {
          c.classList.remove('q');
          c.classList.add('run');
          regions(c).forEach(function (r) { r.classList.add('hit'); });
        }, 500 + i * STEP);
        later(function () {
          var bad = c.hasAttribute('data-fail');
          c.classList.remove('run');
          c.classList.add(bad ? 'bad' : 'ok');
          regions(c).forEach(function (r) { r.classList.remove('hit'); if (bad) r.classList.add('bad'); });
          if (count) count.textContent = String(i + 1);
        }, 500 + i * STEP + STEP - 150);
      });
